Task: Return how many of a, e, i, o, u appear. The string is lowercase.
Signature: int count_vowels(char s[])

Student code:
```c
int is_vowel(char ch) {
    // if ch is equal to any vowel text then return 1
    if (((ch == "a") || (ch == "e") || (ch == "i") || (ch == "o") || (ch == "u"))) {
        return (1); // return 1 to show vowel
    }
    // if not vowel then return 0
    else {
        return (0); // return 0 to show not vowel
    }
}

int count_vowels(char s[]) {
    int i = (0); // set i to 0
    int count = (0); // set vowel count to 0
    // go through the string until null character
    while (((s[i] != '\0'))) { // check if not end of string
        // check if current char is vowel using helper
        if ((is_vowel(s[i])) == 1) {
            count = (count + 1); // increase count by 1
        }
        i = (i + 1); // move to next char
    }
    return (count); // return total vowel count
}
